def montants_vers_paiements(apps, schema_editor):
    """Convertit les montants saisis dans l'ancienne fiche élève en paiements avec reçu."""
    Eleve = apps.get_model('ecole', 'Eleve')
    Paiement = apps.get_model('ecole', 'Paiement')
    for eleve in Eleve.objects.all():
        for champ in ('frais_inscription', 'tranche1', 'tranche2', 'tranche3'):
            montant = getattr(eleve, champ)
            if montant:
                motif = 'inscription' if champ == 'frais_inscription' else champ
                p = Paiement.objects.create(
                    eleve=eleve, motif=motif, montant=montant, date=eleve.cree_le.date(),
                    reference="Repris de l'ancienne fiche",
                )
                p.numero_recu = f'R{p.date:%Y}-{p.pk:05d}'
                p.save(update_fields=['numero_recu'])


